export interface ConnectorConfig {
  /** Salesforce instance base URL, e.g. https://mycompany.my.salesforce.com */
  instanceUrl: string
  /** Bearer access token for Salesforce REST API */
  accessToken: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface HubSpotDealWebhookPayload {
  subscriptionId: string
  portalId: string
  eventId: string
  subscriptionType: string
  attemptNumber: number
  objectId: string
  objectTypeId: string
  changeSource: string
  timestamp: number
  propertyName: string
  propertyValue: string
  previousPropertyValue: string
  object: {
    id: string
    properties: {
      dealname?: string
      amount?: string
      closedate?: string
      website?: string
      hubspot_owner_id?: string
      [key: string]: string | undefined
    }
  }
}

export interface HandleResult {
  salesforceAccountId: string
  action: 'upserted' | 'created'
  website: string
  dealId: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function buildHeaders(accessToken: string): HeadersInit {
  return {
    Authorization: `Bearer ${accessToken}`,
    'Content-Type': 'application/json',
  }
}

async function searchAccountByWebsite(
  config: ConnectorConfig,
  website: string,
): Promise<{ totalSize: number; records: Array<{ Id: string; Website: string }> }> {
  const encodedWebsite = encodeURIComponent(website)
  const url = `${config.instanceUrl}/services/data/v60.0/query?q=SELECT+Id,Website+FROM+Account+WHERE+Website+%3D+'${encodedWebsite}'`
  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'GET',
    headers: buildHeaders(config.accessToken),
  })
  if (!response.ok) {
    throw new Error(`Salesforce SOQL search failed: ${response.status} ${response.statusText} at ${url}`)
  }
  return response.json() as Promise<{ totalSize: number; records: Array<{ Id: string; Website: string }> }>
}

async function upsertAccount(
  config: ConnectorConfig,
  website: string,
  dealId: string,
): Promise<string> {
  const encodedWebsite = encodeURIComponent(website)
  const url = `${config.instanceUrl}/services/data/v60.0/sobjects/Account/Website__c/${encodedWebsite}`
  const body = {
    Deal_ID__c: dealId,
    Description: 'Synced from HubSpot deal',
  }
  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: buildHeaders(config.accessToken),
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`Salesforce Account upsert failed: ${response.status} ${response.statusText} at ${url}`)
  }
  const data = (await response.json()) as { id: string; success: boolean; errors?: unknown[] }
  if (!data.success) {
    throw new Error(`Salesforce Account upsert returned success=false: ${JSON.stringify(data.errors)}`)
  }
  return data.id
}

async function createAccount(
  config: ConnectorConfig,
  website: string,
  dealId: string,
  dealName?: string,
): Promise<string> {
  const url = `${config.instanceUrl}/services/data/v60.0/sobjects/Account/`
  const body = {
    Name: dealName ?? `HubSpot Deal ${dealId}`,
    Website: website,
    Deal_ID__c: dealId,
    Description: 'Created from HubSpot deal sync',
  }
  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: buildHeaders(config.accessToken),
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`Salesforce Account create failed: ${response.status} ${response.statusText} at ${url}`)
  }
  const data = (await response.json()) as { id: string; success: boolean; errors?: unknown[] }
  if (!data.success) {
    throw new Error(`Salesforce Account create returned success=false: ${JSON.stringify(data.errors)}`)
  }
  return data.id
}

export async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.object?.id) {
    throw new Error('Missing required field: object.id (HubSpot deal ID)')
  }
  if (!payload.object?.properties?.website) {
    throw new Error('Missing required field: object.properties.website (HubSpot deal website)')
  }

  const dealId = payload.object.id
  const website = payload.object.properties.website
  const dealName = payload.object.properties.dealname

  const searchResult = await searchAccountByWebsite(config, website)

  if (searchResult.totalSize === 0) {
    const accountId = await createAccount(config, website, dealId, dealName)
    return {
      salesforceAccountId: accountId,
      action: 'created',
      website,
      dealId,
    }
  }

  if (searchResult.totalSize === 1) {
    const accountId = await upsertAccount(config, website, dealId)
    return {
      salesforceAccountId: accountId,
      action: 'upserted',
      website,
      dealId,
    }
  }

  throw new Error(`Multiple Salesforce Accounts found for website ${website} (count: ${searchResult.totalSize}). Expected unique Website field.`)
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, HubSpotDealWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      instanceUrl: 'https://test.my.salesforce.com',
      accessToken: 'test-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.salesforceAccountId).toBe('001XXXXXXXXXXXXXXX')
    expect(result.action).toBe('upserted')
    expect(result.website).toBe('https://example.com')
    expect(result.dealId).toBe('98765')
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    instanceUrl: 'https://test.my.salesforce.com',
    accessToken: 'test-access-token',
  }

  it('creates new Account when no match found', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, done: true, records: [] })
      }
      if (req.url.includes('/sobjects/Account/') && req.method === 'POST') {
        expect(req.json).toEqual({
          Name: 'Q4 Enterprise Deal',
          Website: 'https://example.com',
          Deal_ID__c: '98765',
          Description: 'Created from HubSpot deal sync',
        })
        return jsonResponse({ id: '001NEWACCOUNT123', success: true, errors: [] }, 201)
      }
      return jsonResponse({ error: 'unexpected' }, 404)
    })

    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })
    expect(result.action).toBe('created')
    expect(result.salesforceAccountId).toBe('001NEWACCOUNT123')
    expect(calls.length).toBe(2)
    expect(calls[0].method).toBe('GET')
    expect(calls[1].method).toBe('POST')
  })

  it('upserts existing Account when match found', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({
          totalSize: 1,
          done: true,
          records: [{ Id: '001EXISTING456', Website: 'https://example.com' }],
        })
      }
      if (req.url.includes('/Website__c/') && req.method === 'PATCH') {
        expect(req.json).toEqual({
          Deal_ID__c: '98765',
          Description: 'Synced from HubSpot deal',
        })
        return jsonResponse({ id: '001EXISTING456', success: true, errors: [] })
      }
      return jsonResponse({ error: 'unexpected' }, 404)
    })

    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })
    expect(result.action).toBe('upserted')
    expect(result.salesforceAccountId).toBe('001EXISTING456')
    expect(calls.length).toBe(2)
    expect(calls[0].method).toBe('GET')
    expect(calls[1].method).toBe('PATCH')
  })

  it('throws when object.id is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, object: { ...SOURCE_EXAMPLE.object, id: undefined } } as unknown as HubSpotDealWebhookPayload
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: object.id')
  })

  it('throws when object.properties.website is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, object: { ...SOURCE_EXAMPLE.object, properties: { ...SOURCE_EXAMPLE.object.properties, website: undefined } } } as unknown as HubSpotDealWebhookPayload
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: object.properties.website')
  })

  it('throws on non-2xx SOQL search response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })).rejects.toThrow('Salesforce SOQL search failed: 401 Unauthorized')
  })

  it('throws on non-2xx upsert response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({ totalSize: 1, done: true, records: [{ Id: '001X', Website: 'https://example.com' }] })
      }
      return jsonResponse({ error: 'Conflict' }, 409)
    })
    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })).rejects.toThrow('Salesforce Account upsert failed: 409 Conflict')
  })

  it('throws on non-2xx create response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, done: true, records: [] })
      }
      return jsonResponse({ error: 'Bad Request' }, 400)
    })
    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })).rejects.toThrow('Salesforce Account create failed: 400 Bad Request')
  })

  it('throws when multiple accounts found for website', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ totalSize: 2, done: true, records: [{ Id: '001A', Website: 'https://example.com' }, { Id: '001B', Website: 'https://example.com' }] }))
    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })).rejects.toThrow('Multiple Salesforce Accounts found')
  })

  it('uses dealname for Account Name when creating', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, done: true, records: [] })
      }
      if (req.method === 'POST') {
        expect(req.json).toMatchObject({ Name: 'Q4 Enterprise Deal' })
        return jsonResponse({ id: '001NEW', success: true, errors: [] }, 201)
      }
      return jsonResponse({}, 404)
    })
    await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })
    expect(calls[1].json).toMatchObject({ Name: 'Q4 Enterprise Deal' })
  })

  it('falls back to deal ID for Account Name when dealname missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, object: { ...SOURCE_EXAMPLE.object, properties: { ...SOURCE_EXAMPLE.object.properties, dealname: undefined } } } as unknown as HubSpotDealWebhookPayload
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, done: true, records: [] })
      }
      if (req.method === 'POST') {
        expect(req.json).toMatchObject({ Name: 'HubSpot Deal 98765' })
        return jsonResponse({ id: '001NEW', success: true, errors: [] }, 201)
      }
      return jsonResponse({}, 404)
    })
    await handle(payload, { ...baseConfig, fetch })
    expect(calls[1].json).toMatchObject({ Name: 'HubSpot Deal 98765' })
  })

  it('sends Bearer authorization header', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        expect(req.headers.get('authorization')).toBe('Bearer test-access-token')
        return jsonResponse({ totalSize: 0, done: true, records: [] })
      }
      if (req.method === 'POST') {
        expect(req.headers.get('authorization')).toBe('Bearer test-access-token')
        return jsonResponse({ id: '001NEW', success: true, errors: [] }, 201)
      }
      return jsonResponse({}, 404)
    })
    await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...baseConfig, fetch })
  })

  it('URL-encodes website in SOQL query', async () => {
    const payload = { ...SOURCE_EXAMPLE, object: { ...SOURCE_EXAMPLE.object, properties: { ...SOURCE_EXAMPLE.object.properties, website: 'https://example.com/path with spaces' } } } as unknown as HubSpotDealWebhookPayload
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        expect(req.url).toContain('Website+%3D+%27https%3A%2F%2Fexample.com%2Fpath+with+spaces%27')
        return jsonResponse({ totalSize: 0, done: true, records: [] })
      }
      return jsonResponse({ id: '001NEW', success: true, errors: [] }, 201)
    })
    await handle(payload, { ...baseConfig, fetch })
  })

  it('URL-encodes website in upsert endpoint', async () => {
    const payload = { ...SOURCE_EXAMPLE, object: { ...SOURCE_EXAMPLE.object, properties: { ...SOURCE_EXAMPLE.object.properties, website: 'https://example.com/path with spaces' } } } as unknown as HubSpotDealWebhookPayload
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/query')) {
        return jsonResponse({ totalSize: 1, done: true, records: [{ Id: '001X', Website: 'https://example.com/path with spaces' }] })
      }
      if (req.url.includes('/Website__c/')) {
        expect(req.url).toContain('/Website__c/https%3A%2F%2Fexample.com%2Fpath+with+spaces')
        return jsonResponse({ id: '001X', success: true, errors: [] })
      }
      return jsonResponse({}, 404)
    })
    await handle(payload, { ...baseConfig, fetch })
  })
})

